use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let data = input.as_array().unwrap();
    let mut finish_times = Vec::new();
    let mut current_finish = 0;
    let mut previous_finish = 0;

    for item in data {
        let arrival = item.as_i64().unwrap();
        let duration = item.as_i64().unwrap();
        current_finish = current_finish.max(previous_finish + arrival);
        finish_times.push(serde_json::Value::from(current_finish));
    }

    Value::Array(finish_times)
}
